<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('receipt-lines'),tpl=document.getElementById('receipt-line-template');document.getElementById('add-line').addEventListener('click',()=>{const node=tpl.content.firstElementChild.cloneNode(true),i=list.querySelectorAll('.receipt-line').length;node.querySelectorAll('[data-name]').forEach(el=>el.name=`items[${i}][${el.dataset.name}]`);list.append(node)});list.addEventListener('click',e=>{const btn=e.target.closest('.remove-line');if(btn&&list.querySelectorAll('.receipt-line').length>1)btn.closest('.receipt-line').remove()})});</script>
